/**
 * build/island-bundle.js — compile the islands a static build needs into one
 * browser bundle, and put a script tag on the pages that use them.
 *
 * ── Why a second Vite build ───────────────────────────────────────────────
 * The island set is not known until prerendering has run, and prerendering runs
 * in `closeBundle` — after the main build has finished. Vite's transform hook sees
 * every `.mesa` in the tree earlier, and islands could ride along as extra
 * rollup inputs of the MAIN build on the strength of that. It would be faster
 * and it would be wrong: transform sees the whole route tree, while only
 * `render: static` routes get prerendered and only those pages carry markers.
 * A `render: static` route is the unit of control, and only the prerenderer
 * knows which pages those turned out to be. (Sierra used to keep exactly that
 * over-broad map, `sierraContext.islandMap`, and never read it. It is gone.)
 *
 * So: one extra Vite build, over an entry generated from what prerendering
 * actually emitted. It reuses the caller's plugin list, so `.mesa` compiles the
 * same way it does in the main build — a second, differently-configured Mesa
 * compiler is exactly the kind of hand-copy that drifts.
 *
 * ── One chunk per island ──────────────────────────────────────────────────
 * The generated entry is a table of dynamic imports, so rollup emits a chunk
 * per island and the browser fetches one only when that island's directive
 * fires. That is what makes the directives worth declaring: a `client:visible`
 * island below the fold costs nothing until it is scrolled to, and a
 * `client:media` island whose query never matches is never fetched at all.
 * Both are verified against resource timing in a real browser by
 * `tests/fixtures/island-site/verify.mjs`.
 *
 * The entry itself is shared across every page that has any island. It carries
 * the Mesa runtime and the loader, which are needed by all of them.
 */

import { resolve } from 'path'
import { mkdir, writeFile, readFile, rm } from 'fs/promises'

/**
 * Source for the generated entry: a name → lazy-import table, then hydrate.
 *
 * The registry is keyed by component NAME because that is what the renderer
 * writes into the marker — it has no module path to write, since the marker is
 * produced during a server render where module identity is a temp file.
 */
export function islandEntrySource(islands, {
  loaderSpecifier = '@frontierjs/sierra/islands',
  theme = null,
} = {}) {
  const entries = islands
    .map((isl) => `  ${JSON.stringify(isl.component)}: () => import(${JSON.stringify(isl.module)}),`)
    .join('\n')

  // The theme block, or nothing. A static page never loads `virtual:sierra` —
  // it ships HTML plus these chunks and nothing else — so this entry is the one
  // place a prerendered site can be told what its app declared. Without it the
  // theme module keeps `normalize({})`: DEFAULT_THEMES and key `theme`, so an
  // app declaring six themes had four of them refused by name, and persisted
  // under a key the build's own flash-prevention script does not read, which
  // made every reload revert (`FJS-501`).
  //
  // Serialized rather than imported, because there is no module here to import
  // it FROM — the config is a Node-side object that never entered the browser
  // graph on this target.
  const themeInit = theme
    ? `import { initTheme } from '@frontierjs/sierra/theme'\n` +
      `\n// The app's theme block, carried over from sierra.config.js.\n` +
      `initTheme(${JSON.stringify(theme)})\n`
    : ''

  return `// Generated by @frontierjs/sierra — do not edit.
// One entry per static build, listing the islands its prerendered pages use.
import { hydrateIslands } from ${JSON.stringify(loaderSpecifier)}
${themeInit}
// Dynamic imports, so each island is its own chunk and the code for one is
// fetched only when its directive fires. That is what makes client:visible and
// client:media worth declaring: a below-the-fold island costs nothing until it
// scrolls into view, and a desktop-only one costs nothing on a phone. This
// entry stays tiny — it is a table of import thunks, not the components.
const registry = {
${entries}
}

// Markers are in the served HTML, so the DOM is parsed by the time a module
// script runs — no DOMContentLoaded wait needed, since type="module" defers.
hydrateIslands(registry)
`
}

/**
 * Build the island bundle.
 *
 * @param {object}   opts
 * @param {Array<{component: string, module: string}>} opts.islands
 * @param {string}   opts.root      — Vite root
 * @param {string}   opts.outDir    — absolute output dir (same as the main build's)
 * @param {Array}    opts.plugins   — the main build's Sierra plugin list, reused
 * @param {string}   [opts.base='/']
 * @param {object}   [opts.theme]   — the app's `theme` block, so the switcher on a
 *                                  prerendered page knows what the app declared
 * @param {Function} opts.viteBuild — `build` from vite, injected so this file
 *                                    stays testable without spawning a build
 * @returns {Promise<{ src: string, fileName: string }>} URL and emitted filename
 */
export async function buildIslandBundle(opts) {
  const {
    islands, root, outDir, plugins = [], base = '/', viteBuild, theme = null,
    // An island bundle is only ever built inside a `vite build`, so the answer
    // is Vite's own default and not the ambient env — the sibling in
    // `build/index.js` shipped an unminified production bundle off it
    // (`FJS-799`). A caller that genuinely wants readable islands passes false.
    minify = true,
  } = opts

  if (!islands.length) return null

  // The entry is written to disk rather than served as a virtual module: it
  // imports the island components by ABSOLUTE path, and a virtual module has no
  // directory for Vite to resolve anything relative to. A real file inside the
  // project root also stays inside Vite's fs.allow boundary.
  const tmpDir  = resolve(root, 'node_modules/.sierra')
  const entry   = resolve(tmpDir, 'islands-entry.js')
  await mkdir(tmpDir, { recursive: true })
  await writeFile(entry, islandEntrySource(islands, { theme }), 'utf8')

  let fileName
  try {
    const result = await viteBuild({
      root,
      base,
      configFile: false,           // do not re-read the app's config and recurse
      logLevel: 'warn',
      plugins,
      build: {
        outDir,
        emptyOutDir: false,        // the main build's output is already here
        minify,
        cssCodeSplit: false,
        rollupOptions: {
          input: entry,
          output: {
            entryFileNames: 'assets/islands-[hash].js',
            // Per-island chunks keep their component's name, so a network tab
            // says which island cost what.
            chunkFileNames: 'assets/island-[name]-[hash].js',
          },
        },
      },
    })

    // `build()` resolves to a RollupOutput (or an array of them, for multiple
    // outputs). Find the entry chunk — its name is what the pages must load.
    const outputs = Array.isArray(result) ? result : [result]
    for (const o of outputs) {
      for (const chunk of o.output ?? []) {
        if (chunk.type === 'chunk' && chunk.isEntry) { fileName = chunk.fileName; break }
      }
      if (fileName) break
    }
  } finally {
    await rm(entry, { force: true }).catch(() => {})
  }

  if (!fileName) {
    throw new Error(
      '[Sierra islands] the island bundle built but produced no entry chunk. ' +
      'Nothing can be injected into the prerendered pages, so they would ship inert.'
    )
  }

  return { src: base.replace(/\/$/, '') + '/' + fileName, fileName }
}

/**
 * Put `<script type="module" src=…>` before `</body>`.
 *
 * Returns the html unchanged if the tag is already there, so re-running a build
 * over an existing output directory cannot stack duplicates.
 */
export function injectIslandScript(html, src) {
  if (html.includes(`src="${src}"`)) return html
  const tag = `<script type="module" src="${src}"></script>`
  const i = html.lastIndexOf('</body>')
  if (i === -1) return html + '\n' + tag + '\n'
  return html.slice(0, i) + tag + '\n' + html.slice(i)
}

/**
 * Inject the island script into every prerendered page that has an island.
 *
 * Pages without one are left alone — that is the whole point of islands, and a
 * static page with no interactive component should ship no JavaScript at all.
 *
 * @returns {Promise<string[]>} the files that were modified
 */
export async function injectIntoPages(outDir, islandPages, src) {
  const touched = []
  for (const [rel, names] of islandPages) {
    if (!names || names.size === 0) continue
    const file = resolve(outDir, rel)
    let html
    try {
      html = await readFile(file, 'utf8')
    } catch {
      continue   // prerender reported it, but it is not on disk — nothing to do
    }
    const next = injectIslandScript(html, src)
    if (next !== html) {
      await writeFile(file, next, 'utf8')
      touched.push(rel)
    }
  }
  return touched
}
